KPS_st.name='KPS'; 
KPS_st.lat=46.966;
KPS_st.lon=19.583;
KPS_st.alt=125;
KPS_st.env='con';
KPS_st.footp='RB';
%%

KPS_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_K-puszta.nc',KPS_st.name); %[output:05b814f1]
names_rd=fieldnames(KPS_rd);
%%

datevec(KPS_rd.Time(1)) % 2006 %[output:9daecaff]
datevec(KPS_rd.Time(end)) %2021 %[output:123997d6]
prctile(KPS_rd.U450_S,[5 50 95]) % 95% == 41% should beok %[output:0388ba9f]
plotFigControl(KPS_rd,KPS_st.name); %[output:9ff4c0d0] %[output:088b91af] %[output:7aecdb1a] %[output:4061e1e9] %[output:99748158] %[output:6f26ea63] %[output:90284135] %[output:63cbccb0]
% 1 size cut, ok
% sc: ok, max in winter, no negatives
% abs: 1 size cut, max in winter, no negatives
% abs: clear seasonal cycle of the exponent: max in winter (1.8, min 1 in summer)
%%
% do one time series with PM1 and PM10
P1=timerange('2006-01-01','2008-04-29');
P2=timerange('2008-04-29','2022-01-01');
% B
KPS_rd.BsB_S=NaN(size(KPS_rd.BsB1_S));
KPS_rd.BsB_S(P1)=KPS_rd.BsB1_S(P1);
KPS_rd.BsB_S(P2)=KPS_rd.BsB0_S(P2);

% G
KPS_rd.BsG_S=NaN(size(KPS_rd.BsGtsi1_S));
KPS_rd.BsG_S(P1)=KPS_rd.BsGtsi1_S(P1);
KPS_rd.BsG_S(P2)=KPS_rd.BsGtsi0_S(P2);
% R
KPS_rd.BsR_S=NaN(size(KPS_rd.BsRtsi1_S));
KPS_rd.BsR_S(P1)=KPS_rd.BsRtsi1_S(P1);
KPS_rd.BsR_S(P2)=KPS_rd.BsRtsi0_S(P2);

%Bbs
% B
KPS_rd.BbsB_S=NaN(size(KPS_rd.BbsB1_S));
KPS_rd.BbsB_S(P1)=KPS_rd.BbsB1_S(P1);
KPS_rd.BbsB_S(P2)=KPS_rd.BbsB0_S(P2);

% G
KPS_rd.BbsG_S=NaN(size(KPS_rd.BbsGtsi1_S));
KPS_rd.BbsG_S(P1)=KPS_rd.BbsGtsi1_S(P1);
KPS_rd.BbsG_S(P2)=KPS_rd.BbsGtsi0_S(P2);
% R
KPS_rd.BbsR_S=NaN(size(KPS_rd.BbsRtsi1_S));
KPS_rd.BbsR_S(P1)=KPS_rd.BbsRtsi1_S(P1);
KPS_rd.BbsR_S(P2)=KPS_rd.BbsRtsi0_S(P2);
%%
% BP detection for scat coef and backscat

names_sc={'BsB_S', 'BsG_S', 'BsR_S'};
break_KPS_scat_BP=change_point_analysis_Def(KPS_rd,names_sc,0.05,'KPS','scattering'); %[output:3fe2d2b3] %[output:04491488] %[output:40b56265] %[output:8da25309]
T_KPS_scat_BP=make_table_breakpoints_def(break_KPS_scat_BP);

names_bsc={'BbsB_S', 'BbsG_S', 'BbsR_S'};
break_KPS_bscat_BP=change_point_analysis_Def(KPS_rd,names_bsc,0.05,'KPS','Backscattering'); %[output:8bf0b26f] %[output:6108d951] %[output:61d09bd0] %[output:75dbf212]
T_KPS_bscat_BP=make_table_breakpoints_def(break_KPS_bscat_BP);
%%
% put all abs in one time series
% do one time series with PM1 and PM10
P1=timerange('2006-01-01','2008-04-29');
P2=timerange('2008-04-29','2013-01-01');
P3=timerange('2013-01-01','2022-01-01');

% G
KPS_rd.BaG_A=NaN(size(KPS_rd.Ba5501_A));
KPS_rd.BaG_A(P1)=KPS_rd.Ba5501_A(P1);
KPS_rd.BaG_A(P2)=KPS_rd.Ba5500_A(P2);
KPS_rd.BaG_A(P3)=KPS_rd.Ba5280_A(P3);

%%
