KPS_rd.Properties.VariableNames{9}='BaG0_A';
KPS_rd.Properties.VariableNames{11}='BaR0_A';

%%
% BP detection for abs
names_abs={'BaG_A'};
break_KPS_abs_BP=change_point_analysis_Def(KPS_rd,names_abs,0.05,'KPS','Absorption'); %[output:47d9a858] %[output:9410fe77]
T_KPS_abs_BP=make_table_breakpoints_def(break_KPS_abs_BP); %[output:0ac3b521] %[output:97771817]
%%
lambdaSC=[450;550;700];
lambdaAE=[467;530;660];
%lambdaAE7=[370 470 520 590 660 880 950];
KPS_cal=compute_exp_SSA(KPS_rd,lambdaSC, lambdaAE);
KPS_cal2=compute_exp_D(KPS_rd,{'BaB0_A' ,'BaG0_A', 'BaR0_A'}, lambdaAE);
KPS_cal=outerjoin(KPS_cal,KPS_cal2);
plotFigControl_cal(KPS_cal, KPS_st.name); %[output:3ff27c8e]
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg3', 'expS_br3', 'expS_gr3'};
break_KPS_exps_BP=change_point_analysis_Def(KPS_cal,names_exps,0.05,'KPS','scattering exp'); %[output:7f0230aa] %[output:699db71a] %[output:1b674d8f] %[output:048d6c2d]
T_KPS_exps_BP=make_table_breakpoints_def(break_KPS_exps_BP); %[output:00b507b7] %[output:8daaab13] %[output:07bc8aef] %[output:532a4c0f] %[output:5eaee589]

names_expA={'expA_bg', 'expA_br', 'expA_gr'};
break_KPS_expA_BP=change_point_analysis_Def(KPS_cal,names_expA,0.05,'KPS','Abs exp'); %[output:55571167] %[output:867fda2d] %[output:6ca26954] %[output:8309a766]
T_KPS_expA_BP=make_table_breakpoints_def(break_KPS_expA_BP);

names_BbF={'BbsFG'};
break_KPS_BbF_BP=change_point_analysis_Def(KPS_cal,names_BbF,0.05,'KPS','backscat fraction'); %[output:60ed4fa4] %[output:7b05a633]
T_KPS_BbF_BP=make_table_breakpoints_def(break_KPS_BbF_BP);

names_SSA={'SSA211'};
